  if (!("occurred_at" in v)) errors.push("DeviceAttestation.occurred_at: missing required property");
  else if (!((typeof v.occurred_at === "string" && isRfc3339DateTime(v.occurred_at)))) errors.push("DeviceAttestation.occurred_at: invalid value");
  if (!("expires_at" in v)) errors.push("DeviceAttestation.expires_at: missing required property");
  else if (!((typeof v.expires_at === "string" && isRfc3339DateTime(v.expires_at)))) errors.push("DeviceAttestation.expires_at: invalid value");
  if (!("signer_key_id" in v)) errors.push("DeviceAttestation.signer_key_id: missing required property");
  else if (!((typeof v.signer_key_id === "string" && v.signer_key_id.length >= 1 && v.signer_key_id.length <= 128 && new RegExp("^[A-Za-z0-9._-]+$").test(v.signer_key_id)))) errors.push("DeviceAttestation.signer_key_id: invalid value");
